from collections import deque
# bitmask 10x10 stamps
full=(1<<100)-1
def mask_rows(rows):
    m=0
    for r,cols in enumerate(rows):
        for c in cols:m|=1<<(r*10+c)
    return m
N=mask_rows([range(10) if r<5 else [] for r in range(10)])
S=mask_rows([range(10) if r>=5 else [] for r in range(10)])
W=mask_rows([range(5) for r in range(10)])
E=mask_rows([range(5,10) for r in range(10)])
NW=mask_rows([range(10-r) for r in range(10)])
NE=mask_rows([range(r,10) for r in range(10)])
SW=mask_rows([range(r+1) for r in range(10)])
SE=mask_rows([range(9-r,10) for r in range(10)])
target=NW&W
stamps={'N':N,'S':S,'W':W,'E':E,'NW':NW,'NE':NE,'SW':SW,'SE':SE}
start=0
q=deque([start]); prev={start:None}
while q:
    s=q.popleft()
    if s==target:break
    for name,m in stamps.items():
        for col in [0,15]:
            ns=(s|m) if col else (s&~m)
            if ns not in prev:
                prev[ns]=(s,name,col);q.append(ns)
if target in prev:
    path=[];s=target
    while prev[s]:
        old,name,col=prev[s];path.append((name,col));s=old
    print(path[::-1],len(path))
else:print('none',len(prev))
